import{_ as e,o as l,c as d,ah as a}from"./chunks/framework.Bv6G8Ib6.js";const i="/arch-guidelines/assets/case_multitenant_1.nlZWqdxi.png",n="/arch-guidelines/assets/case_multitenant_2.BAgBe59C.png",s="/arch-guidelines/assets/case_multitenant_3.DDhEivWu.png",p=JSON.parse('{"title":"ケーススタディ1: マルチテナントのデータ分離方式","description":"","frontmatter":{"sidebarDepth":4,"title":"ケーススタディ1: マルチテナントのデータ分離方式","author":"フューチャー株式会社","search":false,"head":[["meta",{"name":"robots","content":"noindex, nofollow"}]]},"headers":[],"relativePath":"documents/forSoftSkill/consensus/case_multitenant.md","filePath":"documents/forSoftSkill/consensus/case_multitenant.md"}'),r={name:"documents/forSoftSkill/consensus/case_multitenant.md"};function f(o,t,g,x,h,y){return l(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="ケーススタディ1-マルチテナントのデータ分離方式" tabindex="-1">ケーススタディ1: マルチテナントのデータ分離方式 <a class="header-anchor" href="#ケーススタディ1-マルチテナントのデータ分離方式" aria-label="Permalink to &quot;ケーススタディ1: マルチテナントのデータ分離方式&quot;">​</a></h1><h2 id="題材の設定" tabindex="-1">題材の設定 <a class="header-anchor" href="#題材の設定" aria-label="Permalink to &quot;題材の設定&quot;">​</a></h2><ul><li>相手: 国内の中堅 BtoB SaaS 事業者。人事・勤怠系の SaaS を約3,000社に提供しており、利用企業の大半は中小企業。合意する先はプロダクト責任者</li><li>自分たち: 次期基盤（AWS、Aurora PostgreSQL）の設計と、稼働後の運用保守を受託した開発会社</li><li>現行: 1つの PostgreSQL に全利用企業のデータを格納し、アプリケーションが tenant_id の条件を付けて読み書きしている</li><li>計画: 年明けからデータ層の詳細設計に入り、2028年4月に稼働する</li><li>きっかけ: ここ1年で従業員1万人を超える大手企業との商談が増えたが、セキュリティチェックシートで他社データとの分離方式を問われ、保留や失注が出ている。チェックシートに回答できるよう、次期基盤でデータの分離を強めることは事業部として決まっている</li><li>決めたいこと: データの分離の方式。これが決まらないと、データ層の詳細設計を始められない</li><li>方針（同業で規模が近い SaaS 企業の公開方針から借用）: 大手企業の獲得</li></ul><h2 id="次期基盤における利用企業データの分け方についてのご相談" tabindex="-1">次期基盤における利用企業データの分け方についてのご相談 <a class="header-anchor" href="#次期基盤における利用企業データの分け方についてのご相談" aria-label="Permalink to &quot;次期基盤における利用企業データの分け方についてのご相談&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>大手企業との商談で、物理的な分離などのセキュリティ要求に対応できず、保留や失注になる例が出ています。</p><h3 id="相談事項" tabindex="-1">相談事項 <a class="header-anchor" href="#相談事項" aria-label="Permalink to &quot;相談事項&quot;">​</a></h3><p>次期基盤で、物理的な分離を必須とする大手企業の審査に応じるかどうかと、応じる場合の構成案を相談させてください。</p><p>データの分け方で DB の構成が変わり、稼働後に専用 DB を足すと作り直しに2名で約3か月（現時点の試算）かかります。そのため、システム構築を担う当社としては、年明けからの DB の詳細設計に入る前の、12月中に決まることが好ましいと考えています。</p><h3 id="要件" tabindex="-1">要件 <a class="header-anchor" href="#要件" aria-label="Permalink to &quot;要件&quot;">​</a></h3><ul><li>業務要件 <ul><li>大手企業のセキュリティチェックシートの3つの設問（他社のデータと物理的に分離されているか、自社のデータだけを指定した時点に戻せるか、自社専用の暗号鍵を使えるか）に回答できる</li><li>他社のデータとの分離を、現行のアプリケーションでの絞り込みより強化する</li><li>機能リリースは、利用企業と約束している夜間のメンテナンス枠（週1回、1時間）の中で終える</li></ul></li><li>システム要件 <ul><li>次期基盤は AWS の Aurora PostgreSQL で構築する</li></ul></li><li>その他 <ul><li>DB の詳細設計は年明けから始める</li><li>2028年4月に稼働する</li><li>稼働後の運用保守は当社が担う</li></ul></li></ul><h3 id="構成案と推奨" tabindex="-1">構成案と推奨 <a class="header-anchor" href="#構成案と推奨" aria-label="Permalink to &quot;構成案と推奨&quot;">​</a></h3><p>物理的な分離を求める大手企業だけを専用の DB に分ける方式5 をご提案します。それ以外の利用企業（以下、標準）は共有 DB のまま、DB の機能で他社のデータを読めないようにします。理由は次の3つです。</p><ul><li>チェックシートで回答できずにいた3つの設問のすべてに、大手企業向けに回答できるようになる。止まっている商談を進められる。稼働前の商談でも、稼働後は専用 DB で分離すると回答できる</li><li>大手企業の負荷は専用 DB の中で収まり、標準の利用企業の応答も守れる</li><li>専用 DB を大手企業の分に絞るので、機能リリースはメンテナンス枠に収まり、基盤費も大手企業の社数分で済む</li></ul><p>5つの方式は、全利用企業で1つの DB を共有する共有型（方式1〜3）、利用企業ごとに DB を分ける専用型（方式4）、共有型と専用型を使い分ける組み合わせ型（方式5）の3つの型に分かれます。 物理的な分離は、他社と DB そのものを分けることを指します。同じ DB の中で他社のデータを読めないように制御するものは論理的な分離と呼ばれ、物理的な分離を必須とする審査では認められません。</p><p><img src="'+i+'" alt="構成案と推奨" width="1999" height="903"> 図の色は利用企業を、錠のマークは DB の機能で他社のデータを読めないようにしていることを表します。暗号鍵の意味ではありません。</p><p>方式3 と方式4 は、機能リリースのたびに約3,000か所へ変更をかけるため、メンテナンス枠（週1回、1時間）に収まらず、採用できません。残った方式2 と方式5 を、現行の方式1 と比べます。費用の比は、現時点の仮試算です。</p><p>【凡例】</p><ul><li>✅ 問題がない、⚠️ 条件つきで対応できるか負担がある、❌ 事実上対応できない</li><li>グレーの行: 3つの方式で差が出ない観点</li><li>大手: 物理的な分離を求める大手企業</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"></th><th style="text-align:left;"></th><th>共有型</th><th style="text-align:left;"></th><th>組み合わせ型</th></tr></thead><tbody><tr><td style="text-align:left;">大分類</td><td style="text-align:left;">小分類</td><td style="text-align:left;">観点</td><td>方式1 アプリで分ける（現行）</td><td style="text-align:left;">方式2 DB の機能で分ける</td><td>方式5 標準は共有、大手は専用</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">仕組み</td><td style="text-align:left;">分離手段</td><td>全利用企業のデータを1つの DB に格納し、アプリケーションが読み書きのたびに自社のデータだけに絞る。現行の方式</td><td style="text-align:left;">1つの DB を共有するが、DB の機能で他社のデータを読めないようにする</td><td>標準の利用企業は方式2、物理的な分離を求める大手企業だけ方式4</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">実現手段</td><td>アプリケーションが利用企業の識別番号で絞る</td><td style="text-align:left;">DB の機能で他社のデータを読めないようにする（PostgreSQL の行レベルセキュリティ）</td><td>標準は方式2、大手は方式4</td></tr><tr><td style="text-align:left;">品質</td><td style="text-align:left;">セキュリティ</td><td style="text-align:left;">他社のデータの遮断</td><td>❌ アプリケーションの作りに頼る</td><td style="text-align:left;">✅ DB の機能で遮断</td><td>✅ 大手は DB そのもの、標準は DB の機能</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">大手企業の審査: 物理的な分離</td><td>❌ DB では分離していない</td><td style="text-align:left;">⚠️ 論理的な分離。物理的な分離を必須とする審査は通らず、第三者認証などで個別に交渉する</td><td>✅ 大手企業は物理的に分離。標準は方式2 と同じ</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">大手企業の審査: 専用の暗号鍵</td><td>❌ 使えない</td><td style="text-align:left;">❌ 使えない</td><td>✅ 大手企業は使える</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">信頼性</td><td style="text-align:left;">1社の負荷が他社に及ばないか</td><td>⚠️ 大手1社の月末の集計などが、全利用企業の応答を遅くしうる</td><td style="text-align:left;">⚠️ 同左</td><td>✅ 大手の負荷は専用 DB の中で収まり、標準の利用企業にも及ばない</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">保守性</td><td style="text-align:left;">1社分のデータを戻す時間</td><td>⚠️ 1営業日以内</td><td style="text-align:left;">⚠️ 1営業日以内</td><td>✅ 大手企業は30分程度。標準は1営業日以内</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">運用する対象の数</td><td>✅ DB 1つ</td><td style="text-align:left;">✅ DB 1つ</td><td>⚠️ 共有 DB 1つと大手の数</td></tr><tr><td style="text-align:left;">費用</td><td style="text-align:left;">初期費用</td><td style="text-align:left;">初期構築費</td><td>✅ 追加なし</td><td style="text-align:left;">✅ 追加なし</td><td>⚠️ 方式2 の約1.2倍（専用 DB を自動で用意し更新する仕組みの構築が加わる）。社数によらない</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">アプリケーションの改修</td><td>⚠️ 利用企業を識別する仕組みの改修</td><td style="text-align:left;">⚠️ 同左</td><td>⚠️ 同左</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">データの移行</td><td>⚠️ 現行から全件を移す</td><td style="text-align:left;">⚠️ 同左</td><td>⚠️ 同左</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">運用費</td><td style="text-align:left;">運用委託費</td><td>✅ 現行どおり</td><td style="text-align:left;">✅ 現行どおり</td><td>⚠️ 方式2 の約1.1倍。社数によらない</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">月々の基盤費</td><td>✅ 現行と同程度</td><td style="text-align:left;">✅ 現行と同程度</td><td>⚠️ 大手1社あたり月約10万円</td></tr><tr><td style="text-align:left;">納期</td><td style="text-align:left;">リリースの速さ</td><td style="text-align:left;">機能リリース時の DB 変更</td><td>✅ 1回</td><td style="text-align:left;">✅ 1回</td><td>⚠️ 大手の社数に1を足した回数。自動化により数十分で、メンテナンス枠に収まる</td></tr></tbody></table><p>残った方式2 と方式5 の違いは、大手企業の扱いだけです。物理的な分離を必須とする審査に応じるかどうかと、稼働時から提供するかで、選ぶ方式が決まります。</p><p><img src="'+n+'" alt="構成案と推奨" width="1999" height="934" loading="lazy"></p><p>以上から方式5 をご提案します。構築と運用の費用が増えても、物理的な分離を必須とする大手企業の審査に応じる、という方向について、まずはご所感を伺えますか。方式5 のデメリットと緩和策は、Appendix にまとめました。</p><h3 id="appendix-方式5-のデメリットと緩和策" tabindex="-1">Appendix: 方式5 のデメリットと緩和策 <a class="header-anchor" href="#appendix-方式5-のデメリットと緩和策" aria-label="Permalink to &quot;Appendix: 方式5 のデメリットと緩和策&quot;">​</a></h3><p>物理的な分離を必須とする審査を通せ、大手企業ごとに性能、復元、暗号鍵を個別に保証できます。一方で次の3つのデメリットがあり、それぞれに緩和策を講じます。</p><p><img src="'+s+'" alt="方式5 を選んだ場合" width="1999" height="840" loading="lazy"></p>',26)])])}const c=e(r,[["render",f]]);export{p as __pageData,c as default};
